import json, urllib.request
owner='juliuss1907'; repo='the-trading-guy'; sha='b83fb38292a24f260f7372ab557326b2ba50093d'
url=f'https://api.github.com/repos/{owner}/{repo}/actions/runs?branch=main&head_sha={sha}&per_page=5'
req=urllib.request.Request(url, headers={'Accept':'application/vnd.github+json','User-Agent':'hermes-agent-ci-audit'})
try:
    with urllib.request.urlopen(req, timeout=30) as r:
        data=json.load(r)
    print(json.dumps({'api_ok': True, 'total_count': data.get('total_count'), 'runs': [
        {k: run.get(k) for k in ['id','name','head_sha','status','conclusion','event','created_at','updated_at','html_url']}
        for run in data.get('workflow_runs', [])
    ]}, indent=2))
except Exception as e:
    print(json.dumps({'api_ok': False, 'error': repr(e)}, indent=2))
    raise SystemExit(1)
PYAPI
